{
  "application": "ppt-generation",
  "case_id": "case-owid-vaccination",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 8,
    "audience": "public health professionals and policy analysts reviewing vaccination impact and progress",
    "tone": "data-forward, authoritative, accessible"
  },
  "brief": {
    "title": "The Power of Vaccination: From Smallpox Eradication to COVID-19 in Record Time",
    "one_liner": "A data-driven overview of how vaccines have transformed public health by eliminating or drastically reducing deadly diseases over the past two centuries.",
    "goal": "Audience should understand the historical trajectory of vaccine development, quantify the dramatic reductions in disease burden vaccines have achieved, and recognize remaining challenges in global vaccination coverage."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "The Power of Vaccination: From Smallpox Eradication to COVID-19 in Record Time",
      "objective": "Cover slide with deck title, subtitle summarizing scope (1796–2020), and source attribution to Our World in Data."
    },
    {
      "id": "vaccine-timeline-acceleration",
      "title": "From 100 Years to Under 1 Year: Vaccine Development Is Accelerating",
      "objective": "Show the timeline from pathogen identification to vaccine licensure for key diseases. Use a horizontal bar/timeline chart referencing the vaccination innovation figure. Highlight that early vaccines took decades (typhoid: 105 years) while COVID-19 took under 1 year."
    },
    {
      "id": "us-disease-elimination",
      "title": "100% Case Reduction Achieved for Diphtheria, Polio, and Smallpox in the US",
      "objective": "Present a table or data visualization showing pre-vaccine vs. post-vaccine case and death rates for major diseases in the US. Emphasize the diseases with 100% reduction and those still with remaining burden (pneumococcal, hepatitis)."
    },
    {
      "id": "measles-heatmap-states",
      "title": "Measles Cases Collapsed Across All 50 US States After Vaccine Mandates",
      "objective": "Display the measles heatmap showing state-by-state case rates from 1929–2022, with annotations for the 1963 vaccine, 1971 MMR, and 1980 mandate. Illustrate the dramatic shift from high incidence (100–1,000+ cases per 100,000) before 1963 to near zero after the 1980 mandate, with only sporadic outbreaks."
    },
    {
      "id": "smallpox-eradication-story",
      "title": "Smallpox: The Only Human Disease Eradicated Through Vaccination",
      "objective": "Narrate the smallpox eradication timeline — from WHO resolution in 1959 to the last case in 1977 and certification in 1980. Use the endemic countries chart. Explain why smallpox was uniquely suited for eradication."
    },
    {
      "id": "herd-immunity-mechanism",
      "title": "Herd Immunity: How Vaccinating Many Protects the Most Vulnerable",
      "objective": "Explain the concept of herd immunity with a clear visual or diagram. Note that vaccines protect not just individuals but also newborns, immunocompromised patients, and those on chemotherapy who cannot be vaccinated."
    },
    {
      "id": "remaining-challenges",
      "title": "Gaps Persist: Pneumococcal Disease Shows Only 40% Case Reduction",
      "objective": "Highlight diseases where vaccine impact is still incomplete — pneumococcal disease (40.5% case reduction, 31.3% death reduction), hepatitis A (89%), and acute hepatitis B (83.9%). Discuss access gaps, supply shortages, and trust challenges as barriers."
    },
    {
      "id": "takeaways-and-priorities",
      "title": "Key Takeaways: Vaccines Have Eliminated Deadly Diseases — But the Job Isn't Done",
      "objective": "Summarize 4–5 key findings: vaccines achieved 100% elimination of multiple diseases in the US, development timelines have collapsed from over 100 years to under 1 year, herd immunity protects entire communities, but coverage gaps persist for diseases like pneumococcal disease, hepatitis A, and hepatitis B. End with a forward-looking call to improve access, coverage, and trust in vaccination."
    }
  ]
}

