python3 << 'PYEOF'
from pptx import Presentation

prs = Presentation("/app/output/final_deck.pptx")

# Verify slide 3 table data matches source brief
slide3 = prs.slides[2]  # 0-indexed
for shape in slide3.shapes:
    if shape.has_table:
        table = shape.table
        print("Table data verification:")
        for r in range(len(table.rows)):
            row_data = []
            for c in range(len(table.columns)):
                row_data.append(table.cell(r, c).text)
            print(f"  Row {r}: {row_data}")

# Verify slide 2 bar chart data
print("\nSlide 2 - checking for all disease labels:")
slide2 = prs.slides[1]
for shape in slide2.shapes:
    if shape.has_text_frame:
        t = shape.text_frame.paragraphs[0].text.strip()
        if t in ["Typhoid fever", "Meningitis", "Whooping cough", "Polio", 
                 "Measles", "Chickenpox", "Hepatitis B", "Ebola", "COVID-19"]:
            print(f"  Found: {t}")

# Verify slide 8 findings match key findings from source
print("\nSlide 8 key findings:")
slide8 = prs.slides[7]
for shape in slide8.shapes:
    if shape.has_text_frame:
        for p in shape.text_frame.paragraphs:
            t = p.text.strip()
            if "100%" in t or "collapsed" in t.lower() or "near zero" in t.lower() or "eradicated" in t.lower() or "Gaps persist" in t:
                print(f"  {t[:100]}")
PYEOF

